const formNewsletter=document.getElementById("newsletterForm"),emailInput=document.getElementById("email"),emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;formNewsletter.addEventListener("submit",async e=>{if(e.preventDefault(),!emailInput.value.trim().match(emailRegex))return void showNotification("Adresse mail invalide","red");const t={email:emailInput.value.trim()};try{const e=await fetch("../back/router.php?action=newsletter",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)}),i=await e.json();i.success?showNotification("Inscription réussie","green"):showNotification(i.message,"red")}catch(e){console.error(e)}});